const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app');let catalog={comics:[],announcements:[],ads:[]};let adminData=null;let chapterComicId='';let toastTimer,chapterStatusTimer=null;let auth={authenticated:false,role:null,username:null,user:null,enabled:false,social:null,loading:true};let authNext=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slug=s=>encodeURIComponent(s);const byId=id=>catalog.comics.find(c=>c.id===id);const localChapterPages=chapter=>(Array.isArray(chapter?.pages)?chapter.pages:[]).map(page=>typeof page==='string'?page:(page?.image_url||page?.url||'')).filter(url=>typeof url==='string'&&url.startsWith('/media/'));const hasLocalPages=chapter=>Number(chapter?.pageCount)>0||localChapterPages(chapter).length>0;
const readStore=(key,def=[])=>{try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(def));}catch{return def;}};
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
async function api(path,opts={}){const headers={'content-type':'application/json',...(opts.headers||{})};const res=await fetch(path,{...opts,headers,credentials:'same-origin'});let data={};try{data=await res.json()}catch{}if(!res.ok)throw Error(data.error||`Permintaan gagal (${res.status})`);return data;}
async function load(){await refreshAuth();if(!location.hash||location.hash==='#home')app.innerHTML=`<section class="section" aria-busy="true"><div class="section-heading"><div><h2>Update terbaru</h2><p>Memuat chapter terbaru…</p></div></div>${updateSkeleton()}</section>`;try{catalog=await api('/api/catalog')}catch(e){app.innerHTML=`<div class="empty"><div class="empty-icon">!</div><b>Perpustakaan belum dapat dimuat</b>${esc(e.message)}<p><button class="btn" onclick="location.reload()">Coba lagi</button></p></div>`;return;}render();}
const fallbackCover='https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=700&q=80';
function card(c){const saved=readStore('akuma-favs').includes(c.id);return `<article class="comic-card" data-open="${esc(c.id)}"><div class="cover-wrap"><img loading="lazy" src="${esc(c.cover||fallbackCover)}" alt="Sampul ${esc(c.title)}" onerror="this.src='${fallbackCover}'"><span class="type-tag">${esc(c.type||'Komik')}</span><span class="chapter-tag">${c.chapters?.length?`Ch. ${esc(c.chapters[0].number)}`:'Baru'}</span><button class="favorite-button ${saved?'saved':''}" data-fav="${esc(c.id)}" aria-label="${saved?'Hapus favorit':'Tambah favorit'}">${saved?'♥':'♡'}</button></div><div class="comic-info"><h3>${esc(c.title)}</h3><div class="comic-meta"><span>${esc(c.status||'')}</span><span class="rating">${c.rating?`★ ${esc(c.rating)}`:'—'}</span></div></div></article>`;}
function grid(items,cols=''){return items.length?`<div class="comic-grid ${cols}">${items.map(card).join('')}</div>`:`<div class="empty"><div class="empty-icon">⌕</div><b>Belum ada komik di sini</b>Judul baru akan muncul setelah data tersedia.</div>`;}
function adSlot(label='Ruang iklan — slot belum dikonfigurasi'){return `<div class="ad-slot" aria-label="Slot iklan berlabel"><strong>${esc(label)}</strong></div>`;}
function sectionTitle(title,sub='',link=''){return `<div class="section-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<a class="text-link" href="#${link}">Lihat semua →</a>`:''}</div>`;}
const chapterTime=c=>{const ch=c?.chapters?.[0];const t=ch?.releasedAt?Date.parse(ch.releasedAt):NaN;if(!Number.isNaN(t))return t;const d=ch?.date?Date.parse(ch.date):NaN;return Number.isNaN(d)?0:d;};
const byUpdate=(a,b)=>chapterTime(b)-chapterTime(a);
const isNewRelease=iso=>{const t=Date.parse(iso||'');return !Number.isNaN(t)&&Date.now()-t>=0&&Date.now()-t<86400000;};
function relTime(iso){if(!iso)return '';const t=Date.parse(iso);if(Number.isNaN(t))return '';const diff=(Date.now()-t)/1000;if(diff<60)return 'baru saja';const m=Math.floor(diff/60);if(m<60)return `${m} menit lalu`;const h=Math.floor(diff/3600);if(h<24)return `${h} jam lalu`;const d=Math.floor(diff/86400);if(d<7)return `${d} hari lalu`;return new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(t));}
const chapterWhen=ch=>ch?.releasedAt?relTime(ch.releasedAt):(ch?.date?ch.date:'Terbaru');
function updateCard(c){const chapters=(c.chapters||[]).slice(0,2),newest=chapters[0],href='#detail/'+slug(c.id),label=[c.type,c.status].filter(Boolean).join(' · ')||'Komik';const chHtml=chapters.length?chapters.map(ch=>`<a class="update-chapter" href="#read/${slug(c.id)}/${slug(ch.id)}" title="Buka chapter ${esc(ch.number)}"><span class="update-chapter-no">Ch. ${esc(ch.number)}</span><time class="update-chapter-time" datetime="${esc(ch.releasedAt||'')}">${esc(chapterWhen(ch))}</time></a>`).join(''):'<span class="update-chapter empty">Belum ada chapter</span>';return `<article class="update-card"><a class="update-cover" href="${href}" data-title="${esc(c.title)}" title="${esc(c.title)}"><img loading="lazy" src="${esc(c.cover||fallbackCover)}" alt="Sampul ${esc(c.title)}" onerror="this.parentElement.classList.add('no-img');this.remove()"><span class="update-badge">${esc(label)}</span>${isNewRelease(newest?.releasedAt)?'<span class="update-new">Baru</span>':''}</a><a class="update-card-title" href="${href}" title="${esc(c.title)}">${esc(c.title)}</a><div class="update-chapters">${chHtml}</div></article>`;}
function updateSkeleton(n=12){return `<div class="update-grid" aria-hidden="true">${Array.from({length:n},()=>'<article class="update-card is-skeleton"><div class="update-cover"></div><span class="sk-line"></span><span class="sk-line sk-short"></span></article>').join('')}</div>`;}
function home(){const featured=catalog.comics[0],ann=catalog.announcements||[],recent=[...catalog.comics].sort(byUpdate);let genres=[...new Set(catalog.comics.flatMap(c=>c.genres||[]))];return `<div class="hero-wrap">${adSlot()}<div class="hero-grid"><article class="hero" style="background-image:url('${esc(featured?.banner||'')}')"><div class="hero-content"><span class="eyebrow">Pilihan editor · ${esc(featured?.type||'Manhwa')}</span><h1>${esc(featured?.title||'Cerita baru menanti')}</h1><p>${esc(featured?.synopsis||'Explore kisah pilihan dari berbagai genre.')}</p><div class="hero-actions"><a class="btn" href="#detail/${slug(featured?.id||'')}">Baca sekarang ↗</a><span class="pill">★ ${featured?.rating||'Pilihan'}</span></div></div><div class="hero-cover" aria-hidden="true"></div></article><aside class="announcements"><div class="section-head"><h2>Pengumuman</h2><a class="text-link" href="#about">Semua →</a></div>${ann.slice(0,3).map(x=>`<div class="notice"><span class="notice-icon">✳</span><div><b>${esc(x.title)}</b><small>${esc(x.date)}</small><p>${esc(x.body)}</p></div></div>`).join('')||'<div class="empty">Belum ada pengumuman.</div>'}</aside></div></div>
<section class="section">${sectionTitle('Rekomendasi','Pilihan cerita untuk menemani harimu')}<div class="tabs" id="recommend-tabs"><button class="tab active" data-type="Semua">Semua</button><button class="tab" data-type="Manhwa">Manhwa</button><button class="tab" data-type="Manhua">Manhua</button><button class="tab" data-type="Manga">Manga</button></div><div id="recommend-grid" style="margin-top:16px">${grid(catalog.comics.slice(0,6))}</div></section>
${adSlot('IKLAN · ruang promosi yang dapat dikonfigurasi admin')}<section class="section"><div class="latest-layout"><div>${sectionTitle('Update terbaru','Chapter terbaru dari perpustakaan','catalog')}${recent.length?`<div class="update-grid">${recent.slice(0,12).map(updateCard).join('')}</div>`:'<div class="empty"><div class="empty-icon">↻</div><b>Belum ada update</b>Chapter baru akan tampil di sini setelah tersedia.</div>'}</div><aside class="side-panel"><h3>Explore genre</h3><div class="genre-cloud">${genres.map(g=>`<button class="genre-chip" data-genre="${esc(g)}">${esc(g)}</button>`).join('')}</div></aside></div></section>`;}
function catalogPage(){const params=new URLSearchParams(location.hash.split('?')[1]||'');let search=params.get('q')||'';const type=params.get('type')||'Semua';const status=params.get('status')||'Semua';const genre=params.get('genre')||'Semua';const sort=params.get('sort')||'update';let items=catalog.comics.filter(c=>(!search||`${c.title} ${c.alt||''} ${c.genres?.join(' ')}`.toLowerCase().includes(search.toLowerCase()))&&(type==='Semua'||c.type===type)&&(status==='Semua'||c.status===status)&&(genre==='Semua'||c.genres?.includes(genre)));if(sort==='popular')items.sort((a,b)=>(b.rating||0)-(a.rating||0));else items.sort(byUpdate);const genres=[...new Set(catalog.comics.flatMap(c=>c.genres||[]))];return `<section class="section">${sectionTitle('Explore komik',`${items.length} cerita tersedia`)}<div class="catalog-tools"><input class="control search-control" id="catalog-search" placeholder="Cari judul, kreator, genre…" value="${esc(search)}"><select id="filter-type" class="control">${['Semua','Manhwa','Manhua','Manga'].map(x=>`<option ${x===type?'selected':''}>${x}</option>`).join('')}</select><select id="filter-status" class="control">${['Semua','Berjalan','Tamat','Hiatus'].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select><select id="filter-genre" class="control"><option>Semua</option>${genres.map(x=>`<option ${x===genre?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-sort" class="control"><option value="update" ${sort==='update'?'selected':''}>Pembaruan</option><option value="popular" ${sort==='popular'?'selected':''}>Popularitas</option></select></div><div id="catalog-grid">${grid(items)}</div></section>`;}
function detailPage(id){const c=byId(decodeURIComponent(id));if(!c)return `<div class="empty"><b>Judul tidak ditemukan</b>Komik mungkin sudah dihapus atau tautannya salah.<p><a class="btn" href="#catalog">Kembali ke katalog</a></p></div>`;const chapters=c.chapters||[];const saved=readStore('akuma-favs').includes(c.id);const read=readStore('akuma-history',{});const first=chapters[0];const firstLocal=first&&(hasLocalPages(first)||['QUEUED','DOWNLOADING','FAILED'].includes(first.status));const start=firstLocal?`<a class="btn" href="#read/${slug(c.id)}/${slug(first.id)}">${read[c.id]?'Lanjut membaca':'Mulai membaca'} →</a>`:'<button class="btn" disabled>Chapter lokal belum tersedia</button>';return `<div class="detail-hero" style="--detail-bg:url('${esc(c.banner||c.cover||fallbackCover)}')"><img class="detail-cover" src="${esc(c.cover||fallbackCover)}" alt="Sampul ${esc(c.title)}"><div class="detail-copy"><span class="eyebrow">${esc(c.type)} · ${esc(c.year||'')}</span><h1>${esc(c.title)}</h1><p class="alt">${esc(c.alt||c.author||'')}</p><div class="detail-facts"><span class="fact">★ ${c.rating||'—'}</span><span class="fact">${esc(c.status)}</span><span class="fact">${esc(c.author||'Kreator tidak diketahui')}</span><span class="fact">${chapters.length} chapter tersimpan</span></div><p class="synopsis">${esc(c.synopsis||'Sinopsis belum tersedia.')}</p><div class="genre-cloud">${(c.genres||[]).map(x=>`<a class="genre-chip" href="#catalog?genre=${encodeURIComponent(x)}">${esc(x)}</a>`).join('')}</div><div class="hero-actions" style="margin-top:17px">${start}<button class="btn ghost" data-fav="${esc(c.id)}">${saved?'♥ Tersimpan':'♡ Favorit'}</button></div></div></div><div class="detail-lower"><section><div class="section-heading"><div><h2>Daftar chapter</h2><p>Pilih chapter yang tersimpan lokal untuk mulai membaca.</p></div></div><div class="chapter-list">${chapters.length?[...chapters].map(ch=>{const local=hasLocalPages(ch),processing=['QUEUED','DOWNLOADING','FAILED'].includes(ch.status),href=local||processing?`href="#read/${slug(c.id)}/${slug(ch.id)}"`:'aria-disabled="true"';const label=local?(read[c.id]===ch.id?'Terakhir dibaca':'Baca →'):processing?(ch.status==='FAILED'?'Lihat status':'Sedang diproses'):'Belum tersedia lokal';return `<${local||processing?'a':'div'} class="chapter-row" ${href}><span><b>Chapter ${esc(ch.number)}${ch.title?` · ${esc(ch.title)}`:''}</b><br><small>${esc(ch.date||'')}</small></span><span class="chapter-link">${label}</span></${local||processing?'a':'div'}>`;}).join(''):'<div class="empty">Belum ada chapter lokal. Unggah PDF chapter dari panel admin untuk mulai membaca.</div>'}</div></section><aside class="side-panel"><h3>Informasi sumber</h3><p style="color:#adb3aa;font-size:11px">${c.source?esc(c.source):'Data demo Akuma'}</p><p style="font-size:10px;color:#777e75">${c.externalContent?'Metadata sumber saja. Reader hanya menampilkan halaman yang sudah diunggah dan tersimpan lokal.':'Chapter demo hanya tersedia jika memiliki halaman lokal.'}</p>${adSlot('IKLAN · detail')}</aside></div><section class="comments" id="comments" aria-label="Komentar"></section>`;}
function readerPageBase(id,chid){const c=byId(decodeURIComponent(id));if(!c)return `<div class="empty"><b>Komik tidak ditemukan</b><a class="text-link" href="#catalog">Kembali ke katalog</a></div>`;const ch=c.chapters?.find(x=>x.id===decodeURIComponent(chid));if(!ch)return `<div class="empty"><b>Chapter tidak ditemukan</b><a class="text-link" href="#detail/${slug(c.id)}">Kembali ke detail</a></div>`;if(!ch.pages?.length&&!ch.pdfUrl&&!['QUEUED','DOWNLOADING','FAILED'].includes(ch.status))return `<section class="prose"><span class="eyebrow">${esc(c.title)} · Chapter ${esc(ch.number)}</span><h1>Halaman lokal belum tersedia</h1><p>Reader hanya menampilkan file chapter yang tersimpan di server ini. Unggah PDF chapter melalui panel admin untuk membuat halaman gambar lokal.</p><a class="btn" href="#detail/${slug(c.id)}">← Kembali ke detail</a></section>`;const i=c.chapters.indexOf(ch),prev=c.chapters[i+1],next=c.chapters[i-1];const history=readStore('akuma-history',{});history[c.id]=ch.id;localStorage.setItem('akuma-history',JSON.stringify(history));const head=`<div class="reader-top"><a class="back" href="#detail/${slug(c.id)}">← Detail</a><h1>${esc(c.title)} · Chapter ${esc(ch.number)}</h1><div class="reader-controls"><select class="control reader-select" id="reader-select">${c.chapters.map(x=>`<option value="${esc(x.id)}" ${x.id===ch.id?'selected':''}>Chapter ${esc(x.number)}</option>`).join('')}</select></div></div>`;const nav=`<div class="reader-nav">${prev?`<a class="btn ghost" href="#read/${slug(c.id)}/${slug(prev.id)}">← Sebelumnya</a>`:'<button class="btn ghost" disabled>← Sebelumnya</button>'}<a class="btn" href="#detail/${slug(c.id)}">Daftar chapter</a>${next?`<a class="btn ghost" href="#read/${slug(c.id)}/${slug(next.id)}">Berikutnya →</a>`:'<button class="btn ghost" disabled>Berikutnya →</button>'}</div>`;if(ch.pdfUrl?.startsWith('/media/'))return `${head}<iframe class="reader-pdf" src="${esc(ch.pdfUrl)}" title="${esc(c.title)} chapter ${esc(ch.number)}"></iframe>${nav}`;if(Array.isArray(ch.pages)&&ch.pages.length)return `${head}<div class="reader-local-pages">${ch.pages.map((src,n)=>`<img src="${esc(src)}" loading="lazy" alt="${esc(c.title)} chapter ${esc(ch.number)}, halaman ${n+1}" onerror="this.alt='Halaman gagal dimuat'">`).join('')}</div>${nav}`;return `<div class="empty"><b>Halaman lokal belum tersedia</b>Unggah PDF chapter dari panel admin agar reader menampilkan gambar yang tersimpan di server.</div>`;}
async function readerPage(id,chid){
  const comic=byId(decodeURIComponent(id)), chapter=comic?.chapters?.find(item=>item.id===decodeURIComponent(chid));
  if(!chapter)return readerPageBase(id,chid);
  // Katalog publik tidak memuat daftar halaman; ambil dari endpoint terpisah lalu lengkapi objek chapter di memori.
  try{const detail=await api(`/api/comics/${encodeURIComponent(comic.id)}/chapters/${encodeURIComponent(chapter.id)}/pages`);chapter.pages=detail.pages.map(p=>p.image_url);chapter.fileUrl=detail.fileUrl;if(detail.pdfUrl)chapter.pdfUrl=detail.pdfUrl;chapter.errorMessage=detail.errorMessage||null;chapter.importMethod=detail.kind==='import'?'kiryuu-html':undefined;}catch{}
  if(['QUEUED','DOWNLOADING'].includes(chapter.status))return '<section class="prose"><a class="back" href="#detail/'+slug(comic.id)+'">← Detail</a><h1>'+esc(comic.title)+' · Chapter '+esc(chapter.number)+'</h1><div class="empty"><span class="loader"></span><b>'+ (chapter.status==='QUEUED'?'Menunggu pemrosesan':'Menyiapkan halaman chapter') +'</b>'+(chapter.importMethod==='kiryuu-html'?'Halaman yang diizinkan sedang disimpan ke server lokal.':'PDF sedang diubah menjadi gambar halaman.')+'</div></section>';
  if(chapter.status==='FAILED')return '<section class="prose"><a class="back" href="#detail/'+slug(comic.id)+'">← Detail</a><h1>'+esc(comic.title)+' · Chapter '+esc(chapter.number)+'</h1><div class="empty"><b>PDF belum dapat ditampilkan</b>'+esc(chapter.errorMessage||'Proses konversi gagal.')+(chapter.fileUrl?'<p><a class="btn" href="'+esc(chapter.fileUrl)+'" target="_blank" rel="noopener noreferrer">Buka PDF asli ↗</a></p>':'')+'</div></section>';
  const original=chapter.pages;chapter.pages=localChapterPages(chapter);
  const html=readerPageBase(id,chid);chapter.pages=original;return html;
}
function libraryPage(){const fav=readStore('akuma-favs'),hist=readStore('akuma-history',{});const f=catalog.comics.filter(c=>fav.includes(c.id)),h=Object.entries(hist).map(([id,ch])=>({c:byId(id),ch})).filter(x=>x.c);return `<section class="section">${sectionTitle('Library','Favorit dan bacaan terakhirmu')}<h2 style="margin:20px 0 14px">Lanjut membaca</h2>${h.length?`<div class="update-list">${h.map(x=>`<a class="update-row" href="#read/${slug(x.c.id)}/${slug(x.ch)}"><img class="mini-cover" src="${esc(x.c.cover||fallbackCover)}" alt=""><div><h3>${esc(x.c.title)}</h3><p>Lanjut dari chapter yang terakhir dibaca</p></div><span class="chapter-link">Lanjut →</span></a>`).join('')}</div>`:'<div class="empty"><b>Belum ada riwayat baca</b>Buka komik dan mulai membaca untuk menyimpan progres.</div>'}<h2 style="margin:30px 0 14px">Favorit</h2>${grid(f)}</section>`;}
const legal={about:['Tentang Akuma','Akuma adalah prototipe katalog dan pembaca komik berbahasa Indonesia. Judul, metadata, dan halaman baca yang tersedia saat ini merupakan data demo. Ketersediaan konten dari sumber lain tidak dijamin.'],privacy:['Kebijakan Privasi','Favorit dan riwayat baca disimpan di browser. Akun menyimpan nama pengguna serta hash kata sandi; sesi login memakai cookie HttpOnly. Server menyimpan data katalog dan unggahan lokal di folder data. Hindari memasukkan informasi pribadi ke demo ini.'],terms:['Ketentuan Layanan','Gunakan layanan secara bertanggung jawab dan patuhi hak cipta serta ketentuan sumber masing-masing. Sinkronisasi dibatasi pada metadata publik yang aksesnya diizinkan. Konten demo bukan publikasi komik resmi.'],contact:['Hubungi Kami','Untuk pertanyaan atau permintaan terkait situs demo ini, gunakan formulir di bawah. Pesan tidak dikirim otomatis ke pihak eksternal.'],report:['Laporkan konten','Laporkan judul atau metadata yang tidak akurat, atau konten yang Anda yakini melanggar hak. Formulir ini menyimpan laporan hanya untuk sesi demo dan tidak mengirimkannya ke pihak eksternal.']};
function legalPage(key){const [title,body]=legal[key];return `<article class="prose"><span class="eyebrow">Akuma · informasi</span><h1>${title}</h1><p>${body}</p>${['contact','report'].includes(key)?`<form id="feedback-form" class="form-stack"><label>${key==='report'?'Judul terkait':'Nama'}<input required name="name" placeholder="${key==='report'?'Nama komik atau tautan':'Nama Anda'}"></label><label>Email (opsional)<input name="email" type="email" placeholder="nama@email.com"></label><label>Pesan<textarea required name="message" rows="5" placeholder="Tulis pesan Anda…"></textarea></label><button class="btn">Kirim laporan</button></form>`:''}</article>`;}
function adminLogin(){return `<section class="section auth-layout"><div><span class="eyebrow">Akuma Studio · area khusus</span><h2>Masuk sebagai admin</h2><p>Login admin terpisah dari akun pembaca. Kredensial dikonfigurasi di server.</p><form id="admin-login" class="form-stack"><label>Nama admin<input name="username" autocomplete="username" required></label><label>Kata sandi<input name="password" type="password" autocomplete="current-password" required></label><button class="btn">Masuk ke panel</button><p id="admin-login-error" class="form-error"></p></form><p><a class="text-link" href="#login">Masuk sebagai pembaca →</a></p></div></section>`;}
const SOCIAL_LOGOS={
  google:'<svg viewBox="0 0 24 24" width="18" height="18"><path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.27-4.74 3.27-8.1z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84A11 11 0 0 0 12 23z"/><path fill="#FBBC05" d="M5.84 14.1A6.6 6.6 0 0 1 5.5 12c0-.73.13-1.44.34-2.1V7.06H2.18A11 11 0 0 0 1 12c0 1.78.43 3.45 1.18 4.94l3.66-2.84z"/><path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1A11 11 0 0 0 2.18 7.06l3.66 2.84C6.71 7.31 9.14 5.38 12 5.38z"/></svg>',
  discord:'<svg viewBox="0 0 24 24" width="20" height="20"><path fill="#5865F2" d="M20.32 4.37A19.8 19.8 0 0 0 15.4 2.85a.07.07 0 0 0-.08.04c-.21.38-.45.87-.61 1.25a18.3 18.3 0 0 0-5.49 0 12.6 12.6 0 0 0-.62-1.25.08.08 0 0 0-.08-.04 19.7 19.7 0 0 0-4.88 1.52.07.07 0 0 0-.03.03C.53 9.05-.32 13.58.1 18.06a.08.08 0 0 0 .03.06 19.9 19.9 0 0 0 5.99 3.03.08.08 0 0 0 .08-.03c.46-.63.87-1.3 1.23-1.99a.08.08 0 0 0-.04-.11 13.1 13.1 0 0 1-1.87-.89.08.08 0 0 1-.01-.13l.37-.29a.07.07 0 0 1 .08-.01c3.93 1.79 8.18 1.79 12.06 0a.07.07 0 0 1 .08.01l.37.29a.08.08 0 0 1-.01.13c-.6.35-1.22.65-1.87.89a.08.08 0 0 0-.04.11c.36.7.78 1.36 1.23 1.99a.08.08 0 0 0 .08.03 19.8 19.8 0 0 0 6-3.03.08.08 0 0 0 .03-.05c.5-5.18-.84-9.67-3.55-13.66a.06.06 0 0 0-.03-.03zM8.02 15.33c-1.18 0-2.16-1.08-2.16-2.42 0-1.33.96-2.42 2.16-2.42 1.21 0 2.18 1.1 2.16 2.42 0 1.34-.96 2.42-2.16 2.42zm7.97 0c-1.18 0-2.15-1.08-2.15-2.42 0-1.33.95-2.42 2.15-2.42 1.21 0 2.18 1.1 2.16 2.42 0 1.34-.95 2.42-2.16 2.42z"/></svg>',
  x:'<svg viewBox="0 0 24 24" width="17" height="17"><path fill="#000" d="M18.24 2.25h3.31l-7.23 8.26 8.5 11.24h-6.66l-5.21-6.82-5.97 6.82H1.67l7.73-8.84L1.25 2.25h6.83l4.71 6.23 5.45-6.23zm-1.16 17.52h1.83L7.08 4.13H5.12l11.96 15.64z"/></svg>'
};
function authPanelHtml(title){return `<div class="auth-panel">
  <div class="auth-tabs" role="tablist" aria-label="Cara masuk">
    <button type="button" class="auth-tab active" role="tab" aria-selected="true" data-auth-tab="social">Sosial</button>
    <button type="button" class="auth-tab" role="tab" aria-selected="false" data-auth-tab="password">Kata sandi</button>
  </div>
  ${title?`<h2 id="auth-modal-title" class="auth-title">${esc(title)}</h2>`:''}
  <div class="auth-panels">
  <div class="auth-tabpanel active" data-auth-panel="social" aria-hidden="false">
    <button type="button" class="social-btn" data-social="google"><span class="social-mark" aria-hidden="true">${SOCIAL_LOGOS.google}</span><span>Google</span></button>
    <button type="button" class="social-btn" data-social="discord"><span class="social-mark" aria-hidden="true">${SOCIAL_LOGOS.discord}</span><span>Discord</span></button>
    <button type="button" class="social-btn" data-social="x"><span class="social-mark" aria-hidden="true">${SOCIAL_LOGOS.x}</span><span>X</span></button>
    <p class="form-error" data-auth-error role="alert"></p>
    <div class="auth-divider"><span>ATAU</span></div>
    <p class="auth-hint">Login pertama lewat penyedia akan membuat akun pembaca baru secara otomatis.<br><button type="button" class="auth-link" data-auth-goto="password">Masuk dengan kata sandi</button></p>
  </div>
  <div class="auth-tabpanel" data-auth-panel="password" aria-hidden="true">
    <form id="user-login" class="form-stack">
      <label>Nama pengguna<input name="username" autocomplete="username" required></label>
      <label>Kata sandi<input name="password" type="password" autocomplete="current-password" required></label>
      <button class="btn">Masuk</button>
      <p class="form-error" role="alert"></p>
    </form>
    <p class="auth-hint">Sudah punya akun? Masuk dengan nama pengguna dan kata sandi.</p>
  </div>
  </div>
</div>`;}
const AUTH_ERRORS={cancelled:'Masuk dibatalkan.',failed:'Login gagal. Coba lagi atau gunakan kata sandi.',unconfigured:'Penyedia login belum dikonfigurasi di server.',notenabled:'Fitur login belum aktif di server ini.'};
function userAuthPage(params){const err=params&&params.get('error');return `<section class="section auth-layout"><div><span class="eyebrow">Akun pembaca</span><h2>Masuk</h2><p>Masuk agar favorit, riwayat, dan penanda tersimpan di akunmu — bukan hanya di peramban ini.</p>${err?`<p class="form-error" role="alert">${esc(AUTH_ERRORS[err]||'Login tidak berhasil. Silakan coba lagi.')}</p>`:''}${authPanelHtml()}<p><a class="text-link" href="#library">Lanjut sebagai tamu →</a> · <a class="text-link" href="#admin">Login admin →</a></p></div></section>`;}
async function accountPage(){try{const me=await api('/api/auth/me');if(me.authenticated&&me.role==='user'){const providers=(me.user?.providers||[]).map(p=>AUTH_PROVIDER_LABEL[p]||p).join(', ');return `<section class="section auth-layout"><span class="eyebrow">Akun pembaca</span><h2>Halo, ${esc(me.username)}</h2>${me.user?.avatar_url?`<img class="account-avatar" src="${esc(me.user.avatar_url)}" alt="">`:''}<p>Login lewat ${esc(providers||'kata sandi')}.</p><p>Favorit dan riwayat baca saat ini masih tersimpan di peramban ini. Penanda akun menyusul di pembaruan berikutnya.</p><button class="btn ghost" id="user-logout">Keluar</button><p><a class="text-link" href="#library">Buka library →</a></p></section>`;}}catch{}return userAuthPage();}
const AUTH_PROVIDER_LABEL={google:'Google',discord:'Discord',x:'X'};
function renderNavRole(){const on=auth.role==='admin';['#nav-admin','#nav-admin-mobile','#footer-admin'].forEach(s=>{const el=$(s);if(el)el.hidden=!on;});}
function renderHeader(){renderNavRole();const slot=$('#account-slot');if(!slot)return;if(auth.loading){slot.innerHTML=`<button type="button" class="account-icon account-icon--checking" aria-label="Memuat akun" disabled></button>`;bindHeader();return;}if(auth.authenticated){const name=auth.username||'Akun',initial=esc(String(name).slice(0,1).toUpperCase()),avatar=auth.user?.avatar_url?`<img src="${esc(auth.user.avatar_url)}" alt="" onerror="this.parentElement.textContent='${initial}'">`:initial;slot.innerHTML=`<div class="account-wrap"><button type="button" class="avatar account-button" id="account-menu-btn" aria-haspopup="true" aria-expanded="false" title="${esc(name)}" aria-label="Menu akun ${esc(name)}">${avatar}</button><div class="account-menu" id="account-menu" role="menu" hidden><div class="account-menu-head"><b>${esc(name)}</b><small>${auth.role==='admin'?'Admin':'Pembaca'}</small></div><a role="menuitem" href="#account">Akun</a>${auth.role==='admin'?'<a role="menuitem" href="#admin">Panel admin</a>':'<a role="menuitem" href="#library">Library</a>'}<button type="button" role="menuitem" id="account-menu-logout">Keluar</button></div></div>`;}else{const silhouette=`<svg class="account-icon-svg" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/></svg>`;slot.innerHTML=`<button type="button" class="account-icon account-icon--guest" id="open-auth" aria-label="Masuk" title="Masuk" aria-haspopup="dialog">${silhouette}</button>`;}bindHeader();}
function bindHeader(){const open=$('#open-auth');if(open)open.onclick=()=>openAuthModal();const btn=$('#account-menu-btn'),menu=$('#account-menu');if(btn&&menu)btn.onclick=e=>{e.stopPropagation();const show=menu.hidden;menu.hidden=!show;btn.setAttribute('aria-expanded',String(show));};const logout=$('#account-menu-logout');if(logout)logout.onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});auth={authenticated:false,enabled:auth.enabled,social:auth.social};renderHeader();toast('Kamu telah keluar.');if(location.hash.replace(/^#/,'').split('/')[0]==='account')location.hash='home';};}
async function refreshAuth(){auth.loading=true;renderHeader();try{auth=await api('/api/auth/me');auth.loading=false;}catch{auth={authenticated:false,enabled:false,social:null,loading:false};}renderHeader();return auth;}
function openAuthModal(errorMsg){authNext=null;const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-modal-title" tabindex="-1"><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button><div class="modal-body">${authPanelHtml('Masuk')}</div></div></div>`;root.hidden=false;document.body.classList.add('modal-open');bindAuthPanel(root);if(errorMsg){const err=root.querySelector('[data-auth-error]');if(err)err.textContent=errorMsg;}root.querySelector('[data-auth-tab].active,[data-social],#user-login input')?.focus();}
function closeAuthModal(){const root=$('#modal-root');if(!root||root.hidden)return;root.innerHTML='';root.hidden=true;document.body.classList.remove('modal-open');}
function bindAuthPanel(scope){$$('[data-auth-tab]',scope).forEach(t=>t.onclick=()=>{$$('[data-auth-tab]',scope).forEach(x=>{const on=x===t;x.classList.toggle('active',on);x.setAttribute('aria-selected',String(on));});$$('[data-auth-panel]',scope).forEach(p=>{const on=p.dataset.authPanel===t.dataset.authTab;p.classList.toggle('active',on);p.setAttribute('aria-hidden',String(!on));});});$$('[data-social]',scope).forEach(b=>b.onclick=()=>startSocial(b.dataset.social,scope));$$('[data-auth-goto]',scope).forEach(b=>b.onclick=()=>$(`[data-auth-tab="${b.dataset.authGoto}"]`,scope)?.click());const backdrop=$('.modal-backdrop',scope);if(backdrop)backdrop.onclick=e=>{if(e.target===backdrop)closeAuthModal();};$$('[data-modal-close]',scope).forEach(b=>b.onclick=()=>closeAuthModal());const form=$('#user-login',scope);if(form)form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),err=$('.form-error',form),button=form.querySelector('button[type="submit"]')||form.querySelector('button');if(button)button.disabled=true;if(err)err.textContent='';try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password'),role:'user'})});toast('Berhasil masuk.');await refreshAuth();const next=authNext||sessionStorage.getItem('akuma-login-next');sessionStorage.removeItem('akuma-login-next');const inModal=Boolean(form.closest('#modal-root'));closeAuthModal();if(next)location.hash=String(next).replace(/^#/,'');else if(!inModal)location.hash='account';}catch(error){if(err)err.textContent=error.message;}finally{if(button)button.disabled=false;}};}
function startSocial(provider,scope){const showError=msg=>{const err=scope&&$('[data-auth-error]',scope);if(err)err.textContent=msg;else toast(msg);};if(!auth.enabled)return showError(AUTH_ERRORS.notenabled);if(auth.social&&!auth.social.includes(provider))return showError(AUTH_ERRORS.unconfigured);const rawHash=location.hash.replace(/^#/,'');const current=rawHash.split('/')[0].split('?')[0];const returnTo=current==='login'||current==='register'||!rawHash?'/#home':'/'+location.hash;location.href=`/api/auth/social/${encodeURIComponent(provider)}/start?return_to=${encodeURIComponent(returnTo)}`;}
function adminPage(initial='sync'){if(!adminData)return adminLogin();return `<section class="section"><div class="section-heading"><div><span class="eyebrow">Akuma Studio</span><h2>Panel admin</h2><p>Kelola katalog, chapter, feed metadata, jadwal, pengumuman, dan slot iklan.</p></div><button class="btn ghost" id="admin-logout">Keluar</button></div><div class="admin-grid"><nav class="admin-nav"><button class="${initial==='sync'?'active':''}" data-admin-tab="sync">Konektor & sinkronisasi</button><button class="${initial==='comics'?'active':''}" data-admin-tab="comics">Komik</button><button class="${initial==='chapters'?'active':''}" data-admin-tab="chapters">Chapter</button><button class="${initial==='scan'?'active':''}" data-admin-tab="scan">Scan Import</button><button class="${initial==='autosync'?'active':''}" data-admin-tab="autosync">Auto-Sync</button><button class="${initial==='announcements'?'active':''}" data-admin-tab="announcements">Pengumuman</button><button class="${initial==='ads'?'active':''}" data-admin-tab="ads">Slot iklan</button><button class="${initial==='komentar'?'active':''}" data-admin-tab="komentar">Komentar</button><button class="${initial==='settings'?'active':''}" data-admin-tab="settings">Pengaturan</button></nav><div class="admin-content" id="admin-content">${adminTab(initial)}</div></div></section>`;}
function adminTab(tab){const d=adminData;if(!d)return '';if(tab==='scan')return ScanImport.tabHtml();if(tab==='autosync')return AutoSync.tabHtml();if(tab==='sync')return `<div class="admin-card"><h3>Status sinkronisasi</h3><p>Sumber Demo memakai JSON lokal dengan ilustrasi orisinal. Sinkronisasi terjadwal mengelola metadata; impor satu chapter Kiryuu dilakukan manual dari tab Chapter dan halaman hasilnya disimpan lokal. Tidak ada tautan baca eksternal.</p><label style="font-size:11px"><input type="checkbox" id="schedule-enabled" ${d.settings.scheduleEnabled?'checked':''}> Aktifkan jadwal untuk konektor metadata yang aktif</label></div>${d.connectors.map(c=>{const configurable=['public-feed','kiryuu','demo-source'].includes(c.id);const localDemo=c.id==='demo-source';return `<div class="admin-card" data-connector="${esc(c.id)}"><div class="connector-head"><div><h3>${esc(c.name)}</h3><p>${esc(c.message)}</p><small style="color:#777">Metode: ${esc(c.method)} · Sinkron terakhir: ${c.lastSync?new Date(c.lastSync).toLocaleString('id-ID'):'Belum pernah'}</small></div><span class="state ${esc(c.state)}">${esc(c.state)}</span></div><div class="admin-row"><label style="font-size:10px"><input type="checkbox" class="connector-enabled" ${c.enabled?'checked':''} ${configurable?'':'disabled'}> Aktif</label><input class="feed-url" value="${esc(c.feedUrl||'')}" placeholder="${c.id==='kiryuu'?'https://v7.kiryuu.to/manga/slug/':localDemo?'Fixture lokal project':'https://domain.example/feed.json'}" ${configurable&&!localDemo?'':'disabled'}><select class="interval">${localDemo?`<option value="5" ${c.intervalMinutes<=5?'selected':''}>5 menit</option>`:''}<option value="60" ${!localDemo&&c.intervalMinutes===60?'selected':''}>1 jam</option><option value="360" ${!localDemo&&c.intervalMinutes===360?'selected':''}>6 jam</option><option value="1440" ${c.intervalMinutes===1440?'selected':''}>24 jam</option><option value="4320" ${c.intervalMinutes===4320?'selected':''}>3 hari</option><option value="10080" ${c.intervalMinutes>=10080?'selected':''}>7 hari</option></select><button class="btn save-connector" ${configurable?'':'disabled'}>Simpan</button><button class="btn ghost sync-connector" ${!c.enabled?'disabled':''}>Sinkronkan</button></div></div>`}).join('')}<div class="admin-card"><h3>Kebersihan data</h3><p>Hapus metadata yang masuk melalui konektor.</p><button class="btn danger" id="purge-synced">Hapus data tersinkronisasi</button></div>`;
if(tab==='comics')return `<div class="admin-card"><h3>Tambah manhwa / komik</h3><form id="add-comic" class="form-stack"><label>Gambar sampul<input name="coverFile" type="file" accept="image/png,image/jpeg,image/webp" required></label><label>Nama komik<input name="title" required maxlength="140"></label><label>Deskripsi<textarea name="synopsis" rows="4" maxlength="2000" required></textarea></label><label>Jenis<select name="type"><option>Manhwa</option><option>Manhua</option><option>Manga</option></select></label><label>Metode chapter<select name="mode" id="comic-mode"><option value="pdf">Unggah PDF</option><option value="source">Sumber konten · sinkronisasi</option></select></label><div id="pdf-fields"><label>Nomor chapter<input name="chapterNumber" type="number" min="0" step="0.1"></label><label>Judul chapter (opsional)<input name="chapterTitle"></label><label>File PDF<input name="pdfFile" type="file" accept="application/pdf"></label></div><div id="source-fields" hidden><label>Sumber konten<select name="sourceId">${d.connectors.filter(c=>['demo-source','kiryuu','public-feed'].includes(c.id)).map(c=>`<option value="${esc(c.id)}" ${c.enabled?'':'disabled'}>${esc(c.name)} · ${esc(c.enabled?'aktif':c.state==='akses-dibatasi'?'akses dibatasi':'nonaktif')}</option>`).join('')}</select></label><p>Untuk mengimpor gambar Kiryuu, buka tab Chapter lalu masukkan URL seri dan nomor chapter. Konektor tetap nonaktif sampai aksesnya diuji dan diizinkan.</p></div><label>Kreator (opsional)<input name="author"></label><button class="btn">Simpan komik</button><p id="comic-form-message" class="form-error"></p></form></div><div class="admin-card table-wrap"><table class="admin-table"><thead><tr><th>Judul</th><th>Jenis</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${d.comics.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(c.type)}</td><td>${esc(c.status)}</td><td><button class="btn danger delete-comic" data-id="${esc(c.id)}">Hapus</button></td></tr>`).join('')}</tbody></table></div>`;
if(tab==='chapters'){const selected=d.comics.find(c=>c.id===chapterComicId)||d.comics[0];chapterComicId=selected?.id||'';return `<div class="admin-card"><h3>Kelola chapter</h3><p>Pilih komik, lalu unggah file lokal atau antrekan impor yang diizinkan.</p><div class="admin-row"><select id="chapter-comic" class="control">${d.comics.map(c=>`<option value="${esc(c.id)}" ${c.id===chapterComicId?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div>${selected?`<div style="margin-top:20px;border-top:1px solid #303330;padding-top:15px"><h3>Impor chapter dari halaman publik Kiryuu</h3><p>Masukkan URL seri dan nomor chapter. Worker akan mencari chapter dari daftar seri, mengambil gambar, lalu menyimpan halaman secara lokal. Penolakan akses oleh sumber akan menghentikan konektor.</p><form id="scrape-chapter" class="form-stack"><label>URL halaman seri<input name="seriesUrl" type="url" value="https://v7.kiryuu.to/manga/swordmasters-youngest-son/" placeholder="https://v7.kiryuu.to/manga/nama-seri/" required></label><label>Nomor chapter<input name="number" type="number" min="0" step="0.1" placeholder="mis. 1" required></label><label>Judul (opsional)<input name="title" maxlength="140" placeholder="Chapter 1"></label><button class="btn">Antrekan impor lokal</button><p id="scrape-chapter-message" class="form-error"></p></form></div><div style="margin-top:20px;border-top:1px solid #303330;padding-top:15px"><h3>Tambah gambar chapter lokal</h3><p>Masukkan nomor chapter dan pilih 1–80 gambar sesuai urutan baca. JPG, PNG, atau WebP; total maksimal 28 MB.</p><form id="upload-chapter-images" class="form-stack"><label>Nomor chapter<input name="number" type="number" min="0" step="0.1" required></label><label>Judul chapter (opsional)<input name="title" maxlength="140"></label><label>Gambar halaman<input name="images" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><button class="btn">Simpan gambar lokal</button><p id="chapter-upload-message" class="form-error"></p></form></div>`:'<div class="empty">Tambahkan komik terlebih dahulu.</div>'}</div>${selected?`<div class="admin-card table-wrap"><table class="admin-table"><thead><tr><th>Chapter</th><th>Status / halaman</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody>${(selected.chapters||[]).map(ch=>`<tr><td>${esc(ch.number)} · ${esc(ch.title||'')}</td><td>${esc(ch.status||'Metadata')}${(ch.pageCount||ch.pages?.length)?` · ${ch.pageCount||ch.pages.length} halaman`:''}${ch.errorMessage?`<br><small>${esc(ch.errorMessage)}</small>`:''}</td><td>${esc(ch.date||'')}</td><td><button class="btn danger delete-chapter" data-id="${esc(ch.id)}">Hapus</button></td></tr>`).join('')||'<tr><td colspan="4">Belum ada chapter.</td></tr>'}</tbody></table></div>`:''}`;}
if(tab==='announcements')return `<div class="admin-card"><h3>Terbitkan pengumuman</h3><form id="add-announcement" class="form-stack"><label>Judul<input name="title" required></label><label>Isi<textarea name="body" rows="3"></textarea></label><button class="btn">Terbitkan</button></form></div>${d.announcements.map(a=>`<div class="admin-card"><b>${esc(a.title)}</b><p>${esc(a.date)} · ${esc(a.body)}</p></div>`).join('')}`;
if(tab==='ads')return `<div class="admin-card"><h3>Slot iklan</h3><p>Slot hanya ditampilkan sebagai ruang berlabel. Iklan tidak aktif sampai akun penyedia dan ID unit valid dikonfigurasi.</p>${d.ads.map(a=>`<div class="admin-row"><span style="flex:1">${esc(a.label)}</span><label style="font-size:10px"><input type="checkbox" class="ad-toggle" data-id="${esc(a.id)}" ${a.enabled?'checked':''}> Tampilkan slot</label></div>`).join('')}</div>`;
 if(tab==='komentar')return `<div class="admin-card"><h3>Laporan komentar</h3><p>Komentar yang dilaporkan pembaca. Hapus komentar atau abaikan laporan.</p><div id="report-list"><p>Memuat…</p></div></div>`;
return `<div class="admin-card"><h3>Pengaturan</h3><form id="settings-form" class="form-stack"><label>Penyedia iklan (opsional)<input name="adProvider" value="${esc(d.settings.adProvider||'')}" placeholder="Nama penyedia"></label><label>ID unit iklan<input name="adUnit" value="${esc(d.settings.adUnit||'')}" placeholder="ID unit dari dashboard penyedia"></label><p>Rahasia provider tetap disimpan di server. Belum ada integrasi iklan aktif pada demo ini.</p><button class="btn">Simpan pengaturan</button></form></div>`;}
async function render(){ScanImport.stop();if(typeof AutoSync!=='undefined')AutoSync.stop();Comments.stop();closeAuthModal();const route=location.hash.slice(1)||'home';const [pathPart,queryPart='']=route.split('?');const [name,...parts]=pathPart.split('/');$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===(name==='detail'||name==='read'?'catalog':name)));if(name==='home')app.innerHTML=home();else if(name==='catalog')app.innerHTML=catalogPage();else if(name==='detail')app.innerHTML=detailPage(parts.join('/'));else if(name==='read')app.innerHTML=await readerPage(parts[0],parts[1]);else if(name==='library')app.innerHTML=libraryPage();else if(name==='login')app.innerHTML=auth.authenticated?await accountPage():userAuthPage(new URLSearchParams(queryPart));else if(name==='register'){location.hash='login';return;}else if(name==='account')app.innerHTML=await accountPage();else if(name==='admin'){if(auth.authenticated&&auth.role!=='admin'){toast('Akses admin diperlukan.');location.hash='home';return;}try{adminData=await api('/api/admin')}catch{adminData=null;}app.innerHTML=!adminData?adminPage():(parts[0]==='scan'&&parts[1])?await ScanImport.finalizePage(parts[1]):adminPage(parts[0]==='scan'?'scan':parts[0]==='autosync'?'autosync':parts[0]==='komentar'?'komentar':'sync');}else if(legal[name])app.innerHTML=legalPage(name);else app.innerHTML=home();bind();ScanImport.bindFinalize();window.scrollTo({top:0,behavior:'smooth'});const authQp=new URLSearchParams(queryPart);if(authQp.get('auth')==='error'){openAuthModal(AUTH_ERRORS[authQp.get('error')]||AUTH_ERRORS.failed);try{history.replaceState(null,'',location.pathname+location.search+'#'+pathPart);}catch{}}}
function bind(){
  ScanImport.bind();
  if(typeof AutoSync!=='undefined')AutoSync.bind();
  {const cparts=location.hash.slice(1).split('/');if(cparts[0]==='detail'){const comic=byId(decodeURIComponent(cparts.slice(1).join('/')));if(comic)Comments.mount({comicId:comic.id});}}
  if(chapterStatusTimer){clearInterval(chapterStatusTimer);chapterStatusTimer=null;}const readRoute=location.hash.slice(1).split('/');if(readRoute[0]==='read'){const current=byId(decodeURIComponent(readRoute[1]||''))?.chapters?.find(ch=>ch.id===decodeURIComponent(readRoute[2]||''));if(['QUEUED','DOWNLOADING'].includes(current?.status)){let attempts=0;chapterStatusTimer=setInterval(async()=>{try{const latest=await api('/api/catalog');catalog=latest;const updated=byId(decodeURIComponent(readRoute[1]||''))?.chapters?.find(ch=>ch.id===decodeURIComponent(readRoute[2]||''));attempts++;if(!['QUEUED','DOWNLOADING'].includes(updated?.status)||attempts>=90){clearInterval(chapterStatusTimer);chapterStatusTimer=null;await render();}}catch{attempts++;if(attempts>=90){clearInterval(chapterStatusTimer);chapterStatusTimer=null;}}},2000);}}if(readRoute[0]==='admin'&&document.querySelector('[data-admin-tab].active')?.dataset.adminTab==='chapters'&&adminData?.comics.some(comic=>comic.chapters?.some(ch=>['QUEUED','DOWNLOADING'].includes(ch.status)))){let attempts=0;chapterStatusTimer=setInterval(async()=>{try{const latest=await api('/api/admin');adminData=latest;attempts++;const pending=latest.comics.some(comic=>comic.chapters?.some(ch=>['QUEUED','DOWNLOADING'].includes(ch.status)));if(!pending||attempts>=90){clearInterval(chapterStatusTimer);chapterStatusTimer=null;const tab=document.querySelector('[data-admin-tab].active')?.dataset.adminTab;if(tab==='chapters'){$('#admin-content').innerHTML=adminTab('chapters');bind();}}}catch{attempts++;if(attempts>=90){clearInterval(chapterStatusTimer);chapterStatusTimer=null;}}},2000);}
  const pdfFrame=$('.reader-pdf');if(pdfFrame){const fallback=document.createElement('p');fallback.className='reader-pdf-fallback';fallback.textContent='PDF tidak tampil? ';const link=document.createElement('a');link.href=pdfFrame.src.split('#')[0];link.target='_blank';link.rel='noopener noreferrer';link.textContent='Buka PDF di tab baru ↗';fallback.append(link);pdfFrame.after(fallback);}const pageStrip=$('.reader-local-pages');if(pageStrip){const parts=location.hash.slice(1).split('/'),comic=byId(decodeURIComponent(parts[1]||'')),chapter=comic?.chapters?.find(ch=>ch.id===decodeURIComponent(parts[2]||'')),fileUrl=chapter?.fileUrl||chapter?.pdfUrl;if(fileUrl){const download=document.createElement('p');download.className='reader-pdf-fallback';const link=document.createElement('a');link.href=fileUrl;link.download='';link.textContent='Unduh PDF asli ↓';download.append(link);pageStrip.after(download);}}
  $$('[data-open]').forEach(x=>x.addEventListener('click',e=>{if(e.target.closest('[data-fav]'))return;location.hash=`detail/${slug(x.dataset.open)}`}));
  $$('[data-fav]').forEach(x=>x.addEventListener('click',e=>{e.stopPropagation();let list=readStore('akuma-favs');const id=x.dataset.fav;if(list.includes(id))list=list.filter(v=>v!==id);else list.push(id);localStorage.setItem('akuma-favs',JSON.stringify(list));toast(list.includes(id)?'Ditambahkan ke favorit':'Dihapus dari favorit');render();}));
  $$('[data-genre]').forEach(x=>x.onclick=()=>location.hash=`catalog?genre=${encodeURIComponent(x.dataset.genre)}`);
  const tabs=$('#recommend-tabs');tabs?.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{tabs.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));const items=b.dataset.type==='Semua'?catalog.comics:catalog.comics.filter(c=>c.type===b.dataset.type);$('#recommend-grid').innerHTML=grid(items.slice(0,6));bind();});
  const applyFilters=()=>{const q=$('#catalog-search')?.value||'';const type=$('#filter-type')?.value||'Semua',status=$('#filter-status')?.value||'Semua',genre=$('#filter-genre')?.value||'Semua',sort=$('#filter-sort')?.value||'update';const items=catalog.comics.filter(c=>(!q||`${c.title} ${c.author} ${c.genres?.join(' ')}`.toLowerCase().includes(q.toLowerCase()))&&(type==='Semua'||c.type===type)&&(status==='Semua'||c.status===status)&&(genre==='Semua'||c.genres?.includes(genre)));if(sort==='popular')items.sort((a,b)=>(b.rating||0)-(a.rating||0));$('#catalog-grid').innerHTML=grid(items);bind();};['catalog-search','filter-type','filter-status','filter-genre','filter-sort'].forEach(id=>{const x=$(`#${id}`);if(x)x.oninput=applyFilters;});
  $('#reader-select')?.addEventListener('change',e=>{const r=location.hash.slice(1).split('/');location.hash=`read/${r[1]}/${slug(e.target.value)}`;});
  $('#feedback-form')?.addEventListener('submit',e=>{e.preventDefault();toast('Terima kasih. Pesan tersimpan untuk demo ini.');e.target.reset();});
  $('#admin-login')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password'),role:'admin'})});adminData=await api('/api/admin');render();}catch(err){$('#admin-login-error').textContent=err.message;}});
  if($('.auth-panel'))bindAuthPanel(document);
  $('#user-logout')?.addEventListener('click',async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});await refreshAuth();toast('Kamu telah keluar.');location.hash='home';});
  $('#admin-logout')?.addEventListener('click',async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});adminData=null;await refreshAuth();render();});
  $$('[data-admin-tab]').forEach(b=>b.onclick=()=>{$$('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#admin-content').innerHTML=adminTab(b.dataset.adminTab);bind();});
  $('#chapter-comic')?.addEventListener('change',e=>{chapterComicId=e.target.value;$('#admin-content').innerHTML=adminTab('chapters');bind();});
  $('#add-chapter')?.addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/admin/comics/${encodeURIComponent(chapterComicId)}/chapters`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await refreshAdmin('chapters');toast('Chapter ditambahkan.');}catch(x){toast(x.message);}});
  $('#scrape-chapter')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,message=$('#scrape-chapter-message'),button=form.querySelector('button[type="submit"]')||form.querySelector('button');button.disabled=true;button.textContent='Memasukkan antrean…';message.textContent='';try{const result=await api(`/api/admin/comics/${encodeURIComponent(chapterComicId)}/chapters/scrape`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(result.message||'Impor masuk antrean.');await refreshAdmin('chapters');}catch(error){message.textContent=error.message;}finally{button.disabled=false;button.textContent='Antrekan impor lokal';}});
  $('#upload-chapter-images')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,files=[...form.elements.images.files],total=files.reduce((sum,file)=>sum+file.size,0);if(files.length>80||total>28_000_000){$('#chapter-upload-message').textContent='Pilih maksimal 80 gambar dengan total ukuran 28 MB.';return;}const readFile=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error(`Gagal membaca ${file.name}.`));reader.readAsDataURL(file);});try{const images=await Promise.all(files.map(readFile));await api(`/api/admin/comics/${encodeURIComponent(chapterComicId)}/chapters/images`,{method:'POST',body:JSON.stringify({number:form.elements.number.value,title:form.elements.title.value,images})});await refreshAdmin('chapters');toast(`${files.length} halaman tersimpan di server.`);}catch(error){$('#chapter-upload-message').textContent=error.message;}});
  $$('.delete-chapter').forEach(b=>b.onclick=async()=>{if(!confirm('Hapus metadata chapter ini?'))return;try{await api(`/api/admin/chapters/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});await refreshAdmin('chapters');toast('Chapter dihapus.');}catch(x){toast(x.message);}});
  $$('.save-connector').forEach(b=>b.onclick=async()=>{const card=b.closest('[data-connector]');try{await api(`/api/admin/connectors/${card.dataset.connector}`,{method:'PATCH',body:JSON.stringify({enabled:card.querySelector('.connector-enabled').checked,feedUrl:card.querySelector('.feed-url').value,intervalMinutes:Number(card.querySelector('.interval').value)})});adminData=await api('/api/admin');$('#admin-content').innerHTML=adminTab('sync');bind();toast('Pengaturan konektor tersimpan.');}catch(e){toast(e.message);}});
  $$('.sync-connector').forEach(b=>b.onclick=async()=>{const card=b.closest('[data-connector]');b.disabled=true;b.textContent='Memeriksa…';try{const r=await api(`/api/admin/connectors/${card.dataset.connector}/sync`,{method:'POST',body:'{}'});toast(r.message);}catch(e){toast(e.message);}finally{adminData=await api('/api/admin');$('#admin-content').innerHTML=adminTab('sync');bind();}});
  $('#schedule-enabled')?.addEventListener('change',async e=>{try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({...adminData.settings,scheduleEnabled:e.target.checked})});adminData=await api('/api/admin');$('#admin-content').innerHTML=adminTab('sync');bind();toast('Jadwal tersimpan.');}catch(err){toast(err.message);}});
  $('#purge-synced')?.addEventListener('click',async()=>{if(!confirm('Hapus semua metadata hasil sinkronisasi beserta halaman demo yang tersimpan?'))return;for(const c of adminData.comics.filter(x=>['public-feed','Kiryuu ID','Sumber Demo Lokal'].includes(x.source)))await api(`/api/admin/comics/${encodeURIComponent(c.id)}`,{method:'DELETE'});await refreshAdmin();toast('Data sinkronisasi dan media lokal dihapus.');});
  $('#comic-mode')?.addEventListener('change',e=>{$('#pdf-fields').hidden=e.target.value!=='pdf';$('#source-fields').hidden=e.target.value!=='source';$('#pdf-fields [name=chapterNumber]').required=e.target.value==='pdf';$('#pdf-fields [name=pdfFile]').required=e.target.value==='pdf';});if($('#comic-mode'))$('#comic-mode').dispatchEvent(new Event('change'));
  $('#add-comic')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),readFile=file=>new Promise((resolve,reject)=>{if(!file?.size)return resolve('');const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Berkas gagal dibaca.'));reader.readAsDataURL(file);});try{const payload={title:f.get('title'),synopsis:f.get('synopsis'),author:f.get('author'),type:f.get('type'),mode:f.get('mode'),sourceId:f.get('sourceId'),chapterNumber:f.get('chapterNumber'),chapterTitle:f.get('chapterTitle'),coverData:await readFile(f.get('coverFile')),pdfData:await readFile(f.get('pdfFile'))};const result=await api('/api/admin/comics',{method:'POST',body:JSON.stringify(payload)});await refreshAdmin();toast(result.message||'Komik berhasil disimpan.');}catch(x){$('#comic-form-message').textContent=x.message;}});
  $$('.delete-comic').forEach(b=>b.onclick=async()=>{if(!confirm('Hapus komik ini beserta daftar chapternya?'))return;try{await api(`/api/admin/comics/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});await refreshAdmin();toast('Komik dihapus.');}catch(e){toast(e.message);}});
  $('#add-announcement')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/announcements',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await refreshAdmin('announcements');toast('Pengumuman diterbitkan.');}catch(x){toast(x.message);}});
  $$('.ad-toggle').forEach(x=>x.onchange=async()=>{try{await api('/api/admin/ads',{method:'PATCH',body:JSON.stringify({id:x.dataset.id,enabled:x.checked})});adminData=await api('/api/admin');toast('Slot iklan diperbarui.');}catch(e){toast(e.message);}});
  $('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({...adminData.settings,...Object.fromEntries(new FormData(e.target))})});adminData=await api('/api/admin');$('#admin-content').innerHTML=adminTab('settings');bind();toast('Pengaturan disimpan.');}catch(x){toast(x.message);}});
  const reportList=$('#report-list');if(reportList&&!reportList.dataset.bound){reportList.dataset.bound='1';reportList.addEventListener('click',async e=>{const b=e.target.closest('[data-report-action]');if(!b)return;try{await api(`/api/admin/comment-reports/${encodeURIComponent(b.dataset.cid)}`,{method:'POST',body:JSON.stringify({action:b.dataset.reportAction})});toast(b.dataset.reportAction==='delete'?'Komentar dihapus.':'Laporan diabaikan.');loadReports();}catch(err){toast(err.message);}});}
  if(document.querySelector('[data-admin-tab].active')?.dataset.adminTab==='komentar')loadReports();
}
async function loadReports(){const list=$('#report-list');if(!list)return;try{const data=await api('/api/admin/comment-reports');const rows=data.reports||[];list.innerHTML=rows.length?rows.map(r=>`<div class="report-row"><div class="report-body"><b>${esc(r.userName)}</b> <small>${r.reports} laporan</small><p>${esc(String(r.body||'').slice(0,220))}</p></div><div class="admin-row"><button class="btn danger" data-report-action="delete" data-cid="${esc(r.commentId)}">Hapus komentar</button><button class="btn ghost" data-report-action="ignore" data-cid="${esc(r.commentId)}">Abaikan</button></div></div>`).join(''):'<p class="empty">Tidak ada laporan terbuka.</p>';}catch(e){list.innerHTML=`<p class="form-error">${esc(e.message)}</p>`;}}
async function refreshAdmin(tab='comics'){adminData=await api('/api/admin');catalog=await api('/api/catalog');$('#admin-content').innerHTML=adminTab(tab);bind();}
window.addEventListener('hashchange',render);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAuthModal();});
document.addEventListener('click',e=>{const menu=$('#account-menu');if(menu&&!menu.hidden&&!e.target.closest('.account-wrap')){menu.hidden=true;$('#account-menu-btn')?.setAttribute('aria-expanded','false');}});
HeaderSearch.init({api,esc,slug,fallbackCover});
Comments.init({api,esc,toast,relTime});
renderHeader();
